SELECT c.segment, CASE WHEN c.city IN ('Tokyo', 'Singapore') THEN 'tier_1' ELSE 'other' END AS city_group, ROUND(STDDEV(o.amount), 2) AS stddev_amount, MIN(o.discount) AS min_discount FROM orders o JOIN customers c ON o.customer_id = c.id WHERE o.channel IN ('partner', 'mobile', 'store') GROUP BY c.segment, CASE WHEN c.city IN ('Tokyo', 'Singapore') THEN 'tier_1' ELSE 'other' END HAVING MIN(o.discount) >= 0.39 ORDER BY segment, city_group DESC LIMIT 5;
